import java.util.Scanner;

public class Main {
    static final long MOD = 1000000007;

    static long fastExp(long base, long exp) {
        long res = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                res = (res * base) % MOD;
            }
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return res;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long P = sc.nextLong();
        long K = sc.nextLong();

        boolean[] visited = new boolean[(int) P];
        long[] cycleSizes = new long[(int) P + 1];

        if (K == 0) {
            long prod = 1;
            for (long i = 1; i < P; ++i) {
                prod = (prod * P) % MOD;
            }
            System.out.println(prod);
            sc.close();
            return;
        }
        if (K == 1) {
            long prod = 1;
            for (long i = 1; i <= P; ++i) {
                prod = (prod * P) % MOD;
            }
            System.out.println(prod);
            sc.close();
            return;
        }

        for (long start = 0; start < P; ++start) {
            if (!visited[(int) start]) {
                long length = 0;
                long pos = start;
                while (!visited[(int) pos]) {
                    visited[(int) pos] = true;
                    length++;
                    pos = (K * pos) % P;
                }
                cycleSizes[(int) length]++;
            }
        }

        long answer = 1;
        for (int len = 2; len <= P; ++len) {
            if (cycleSizes[len] != 0) {
                long base = (cycleSizes[len] * len + 1) % MOD;
                long power = fastExp(base, cycleSizes[len]);
                answer = (answer * power) % MOD;
            }
        }
        System.out.println(answer);
        sc.close();
    }
}
